import React from 'react';

export default function GununganGate({ side }: { side: 'left' | 'right' }) {
  // Warna Emas/Antique Brass sesuai palette Sogan lu
  const goldColor = "#BEJI454"; 
  
  return (
    <svg 
      viewBox="0 0 400 600" 
      className="w-full h-auto drop-shadow-2xl"
      xmlns="http://www.w3.org/2000/svg"
    >
      <defs>
        {/* Magic trick: Motong SVG jadi dua otomatis */}
        <clipPath id="clip-left">
          <rect x="0" y="0" width="200" height="600" />
        </clipPath>
        <clipPath id="clip-right">
          <rect x="200" y="0" width="200" height="600" />
        </clipPath>
      </defs>

      <g clipPath={`url(#clip-${side})`}>
        {/* Layer 1: Garis Luar (Gunungan Outline) */}
        <path 
          d="M 200 20 C 280 150, 380 350, 380 580 L 20 580 C 20 350, 120 150, 200 20 Z" 
          fill="none" 
          stroke={goldColor} 
          strokeWidth="6" 
        />
        
        {/* Layer 2: Garis Dalam (Inner Frame) */}
        <path 
          d="M 200 60 C 260 170, 350 360, 350 560 L 50 560 C 50 360, 140 170, 200 60 Z" 
          fill="none" 
          stroke={goldColor} 
          strokeWidth="2" 
          strokeDasharray="8 4"
        />

        {/* Pohon Kehidupan (Pohon Hayat - Elemen Inti Gunungan) */}
        <line x1="200" y1="580" x2="200" y2="150" stroke={goldColor} strokeWidth="4" />
        
        {/* Dahan/Cabang Kanan */}
        <path d="M 200 450 Q 260 400, 300 300" fill="none" stroke={goldColor} strokeWidth="3" />
        <path d="M 200 350 Q 250 320, 270 230" fill="none" stroke={goldColor} strokeWidth="3" />
        <path d="M 200 250 Q 230 220, 240 160" fill="none" stroke={goldColor} strokeWidth="3" />
        
        {/* Dahan/Cabang Kiri */}
        <path d="M 200 450 Q 140 400, 100 300" fill="none" stroke={goldColor} strokeWidth="3" />
        <path d="M 200 350 Q 150 320, 130 230" fill="none" stroke={goldColor} strokeWidth="3" />
        <path d="M 200 250 Q 170 220, 160 160" fill="none" stroke={goldColor} strokeWidth="3" />

        {/* Gerbang Bawah (Candi Bentar Minimalis) */}
        <rect x="150" y="500" width="100" height="80" fill="none" stroke={goldColor} strokeWidth="3" />
        <line x1="150" y1="540" x2="250" y2="540" stroke={goldColor} strokeWidth="2" />
        <line x1="175" y1="500" x2="175" y2="580" stroke={goldColor} strokeWidth="2" />
        <line x1="225" y1="500" x2="225" y2="580" stroke={goldColor} strokeWidth="2" />
      </g>
    </svg>
  );
}